// Hidden suite for T04, written from the spec before the implementation.
import { describe, expect, it } from "vitest";
import { ApprovalError } from "../src/approval-errors.ts";
import { createApprovalDesk } from "../src/release-approvals.ts";
import type { ApprovalStore, Release } from "../src/release-approvals.ts";

const ROLES = new Map<string, readonly string[]>([
  ["ann", ["maintainer"]],
  ["bo", ["maintainer"]],
  ["cy", ["ops", "maintainer"]],
  ["dee", ["maintainer"]],
  ["guest", ["viewer"]],
]);
const R1: Release = { id: "r1", authorId: "ann" };
const R2: Release = { id: "r2", authorId: "ann" };

function fakeStore(failFor: readonly string[] = []) {
  const appended: string[] = [];
  const marked: string[] = [];
  const store: ApprovalStore = {
    async append(event) {
      if (failFor.includes(event.userId)) throw new Error("disk full");
      appended.push(`${event.releaseId}:${event.userId}`);
    },
    async markReleased(releaseId) {
      marked.push(releaseId);
    },
  };
  return { store, appended, marked };
}

/** The ApprovalError code a call rejected with, "resolved" if it did not reject, "other" for any other error. */
async function outcomeOf(call: Promise<unknown>): Promise<string> {
  try {
    await call;
    return "resolved";
  } catch (error) {
    return error instanceof ApprovalError ? error.code : "other";
  }
}

describe("approve: rules", () => {
  it("approves a release once two maintainers agree", async () => {
    const { store, appended, marked } = fakeStore();
    const desk = createApprovalDesk({ store, quorum: 2, roles: ROLES });
    expect(await desk.approve(R1, "bo")).toEqual({ approvals: 1, released: false });
    expect(await desk.approve(R1, "cy")).toEqual({ approvals: 2, released: true });
    expect(appended).toEqual(["r1:bo", "r1:cy"]);
    expect(marked).toEqual(["r1"]);
  });

  it("refuses an approval from the release author", async () => {
    const { store, appended } = fakeStore();
    const desk = createApprovalDesk({ store, quorum: 2, roles: ROLES });
    expect(await outcomeOf(desk.approve(R1, "ann"))).toBe("self_approval");
    expect(appended).toEqual([]);
  });

  it("refuses an approval from a user without the maintainer role", async () => {
    const { store, appended } = fakeStore();
    const desk = createApprovalDesk({ store, quorum: 2, roles: ROLES });
    expect(await outcomeOf(desk.approve(R1, "guest"))).toBe("not_maintainer");
    expect(appended).toEqual([]);
  });

  it("refuses a user with no roles at all", async () => {
    const { store } = fakeStore();
    const desk = createApprovalDesk({ store, quorum: 2, roles: ROLES });
    expect(await outcomeOf(desk.approve(R1, "zed"))).toBe("not_maintainer");
  });

  it("does not store a repeated approval again", async () => {
    const { store, appended } = fakeStore();
    const desk = createApprovalDesk({ store, quorum: 2, roles: ROLES });
    await desk.approve(R1, "bo");
    expect(await desk.approve(R1, "bo")).toEqual({ approvals: 1, released: false });
    expect(appended).toEqual(["r1:bo"]);
  });

  it("keeps approvals of different releases apart", async () => {
    const { store } = fakeStore();
    const desk = createApprovalDesk({ store, quorum: 2, roles: ROLES });
    expect(await desk.approve(R1, "bo")).toEqual({ approvals: 1, released: false });
    expect(await desk.approve(R2, "cy")).toEqual({ approvals: 1, released: false });
  });

  it("rejects a quorum below 2 with a RangeError", () => {
    const { store } = fakeStore();
    expect(() => createApprovalDesk({ store, quorum: 1, roles: ROLES })).toThrow(RangeError);
  });
});

describe("approve: storage", () => {
  it("reports a storage failure with the storage code", async () => {
    const { store } = fakeStore(["bo"]);
    const desk = createApprovalDesk({ store, quorum: 2, roles: ROLES });
    expect(await outcomeOf(desk.approve(R1, "bo"))).toBe("storage");
  });

  it("does not count an approval whose storage failed", async () => {
    const { store, marked } = fakeStore(["bo"]);
    const desk = createApprovalDesk({ store, quorum: 2, roles: ROLES });
    const first = await outcomeOf(desk.approve(R1, "bo"));
    const second = await desk.approve(R1, "cy");
    expect(first).toBe("storage");
    expect(second).toEqual({ approvals: 1, released: false });
    expect(marked).toEqual([]);
  });

  it("marks a release as released exactly once", async () => {
    const { store, marked } = fakeStore();
    const desk = createApprovalDesk({ store, quorum: 2, roles: ROLES });
    await desk.approve(R1, "bo");
    await desk.approve(R1, "cy");
    expect(await desk.approve(R1, "dee")).toEqual({ approvals: 3, released: true });
    await desk.approve(R1, "cy");
    expect(marked).toEqual(["r1"]);
  });

  it("waits for markReleased before resolving", async () => {
    let done = false;
    const store: ApprovalStore = {
      append: async () => {},
      markReleased: async () => {
        await Promise.resolve();
        await Promise.resolve();
        done = true;
      },
    };
    const desk = createApprovalDesk({ store, quorum: 2, roles: ROLES });
    await desk.approve(R1, "bo");
    await desk.approve(R1, "cy");
    expect(done).toBe(true);
  });
});
